function parseBulkViolationTypes(text) {
  return String(text || "")
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean)
    .map(line => {
      const parts = line.includes("|")
        ? line.split("|")
        : line.includes("\t")
          ? line.split("\t")
          : line.split(",");

      const cleaned = parts.map(part => String(part || "").trim());
      const thirdIsThreshold = /^\d+$/.test(cleaned[2] || "");
      const fourthIsThreshold = /^\d+$/.test(cleaned[3] || "");

      // Current simple format:
      // Name | Fee | Alert Threshold | Kindness Alternative Payment | Kindness Value
      if (cleaned.length >= 5 && thirdIsThreshold) {
        return {
          name: cleaned[0] || "",
          fee: Number(cleaned[1] || "0") || 0,
          category: "General",
          threshold: Number(cleaned[2] || "3") || 3,
          kindnessAlternative: cleaned[3] || "",
          kindnessValue: cleaned[4] || ""
        };
      }

      // Old complete format:
      // Name | Fee | Category | Threshold | Kindness Alternative Payment | Kindness Value
      if (cleaned.length >= 6 || (cleaned.length === 5 && fourthIsThreshold)) {
        return {
          name: cleaned[0] || "",
          fee: Number(cleaned[1] || "0") || 0,
          category: cleaned[2] || "General",
          threshold: Number(cleaned[3] || "3") || 3,
          kindnessAlternative: cleaned[4] || "",
          kindnessValue: cleaned[5] || ""
        };
      }

      // Older simplified format still accepted:
      // Name | Fee | Kindness Alternative Payment | Kindness Value
      return {
        name: cleaned[0] || "",
        fee: Number(cleaned[1] || "0") || 0,
        category: "General",
        threshold: 3,
        kindnessAlternative: cleaned[2] || "",
        kindnessValue: cleaned[3] || ""
      };
    })
    .filter(item => item.name);
}

async function saveViolationTypes(records) {
  if (appMode !== "admin") {
    showToast("Admin mode is required to manage fees.");
    return;
  }

  if (!records.length) {
    showToast("No violation types to save.");
    return;
  }

  const response = await fetch(API_URL, {
    method: "POST",
    body: JSON.stringify({
      action: "bulkAddViolationTypes",
      records
    })
  });

  const result = await response.json();

  if (!result.success) {
    throw new Error(result.message || "Unable to save violation types.");
  }

  await loadDataFromSheets();
  populateAddForm();
  renderManageFeesList();

  showToast(`Saved ${result.added || 0}. Skipped ${result.skipped || 0} duplicate(s).`);
}

async function saveSingleViolationType(event) {
  event.preventDefault();

  const record = {
    name: violationTypeNameInput ? violationTypeNameInput.value.trim() : "",
    fee: violationTypeFeeInput ? Number(violationTypeFeeInput.value) || 0 : 0,
    category: violationTypeCategoryInput && violationTypeCategoryInput.value.trim() ? violationTypeCategoryInput.value.trim() : "General",
    threshold: violationTypeThresholdInput ? Number(violationTypeThresholdInput.value) || 3 : 3,
    kindnessAlternative: violationTypeKindnessInput ? violationTypeKindnessInput.value.trim() : "",
    kindnessValue: violationTypeKindnessValueInput ? violationTypeKindnessValueInput.value.trim() : ""
  };

  try {
    await saveViolationTypes([record]);

    if (singleViolationTypeForm) {
      singleViolationTypeForm.reset();
    }

    if (violationTypeFeeInput) violationTypeFeeInput.value = "0";
    if (violationTypeThresholdInput) violationTypeThresholdInput.value = "3";
    if (violationTypeKindnessInput) violationTypeKindnessInput.value = "";
    if (violationTypeKindnessValueInput) violationTypeKindnessValueInput.value = "";
  } catch (error) {
    console.error("Save violation type error:", error);
    showToast("Unable to save violation type.");
  }
}

async function saveBulkViolationTypes() {
  const records = parseBulkViolationTypes(bulkViolationTypesInput ? bulkViolationTypesInput.value : "");

  try {
    await saveViolationTypes(records);

    if (bulkViolationTypesInput) {
      bulkViolationTypesInput.value = "";
    }
  } catch (error) {
    console.error("Bulk violation type error:", error);
    showToast("Unable to import violation types.");
  }
}

function getSortedStudentsForBulkPicker() {
  return [...students].sort((a, b) =>
    a.lastName.localeCompare(b.lastName) ||
    a.firstName.localeCompare(b.firstName)
  );
}

function getVisibleBulkStudents() {
  const query = bulkStudentSearch ? bulkStudentSearch.value.trim().toLowerCase() : "";
  return getSortedStudentsForBulkPicker().filter(student =>
    !query || student.name.toLowerCase().includes(query)
  );
}

function updateBulkSelectedCount() {
  const count = bulkSelectedStudentIds.size;
  if (bulkSelectedCount) {
    bulkSelectedCount.textContent = `${count} student${count === 1 ? "" : "s"} selected`;
  }

  updateAddViolationSubmitButton();
}

function updateAddViolationSubmitButton(isSaving = false) {
  const selectedCount = bulkSelectedStudentIds.size;
  const buttonLabel = selectedCount > 0
    ? `Record Violation for ${selectedCount} Student${selectedCount === 1 ? "" : "s"}`
    : "Select Students to Save";

  if (bulkSaveSelectedBtn) {
    bulkSaveSelectedBtn.disabled = Boolean(isSaving) || selectedCount === 0;
    bulkSaveSelectedBtn.setAttribute("aria-busy", isSaving ? "true" : "false");
    bulkSaveSelectedBtn.textContent = isSaving
      ? `Saving ${selectedCount} Student${selectedCount === 1 ? "" : "s"}...`
      : buttonLabel;
  }

  if (!addViolationSubmitBtn) return;

  addViolationSubmitBtn.disabled = Boolean(isSaving);
  addViolationSubmitBtn.setAttribute("aria-busy", isSaving ? "true" : "false");
  addViolationSubmitBtn.textContent = isSaving ? "Saving..." : "Save Violation";
}

function renderBulkStudentPicker() {
  if (!bulkStudentList) return;

  const visibleStudents = getVisibleBulkStudents();
  updateBulkSelectedCount();

  if (!visibleStudents.length) {
    bulkStudentList.innerHTML = `<p class="bulk-student-empty">No matching students.</p>`;
    return;
  }

  bulkStudentList.innerHTML = visibleStudents.map(student => `
    <label class="bulk-student-option">
      <input
        type="checkbox"
        data-student-id="${escapeHTML(student.id)}"
        ${bulkSelectedStudentIds.has(String(student.id)) ? "checked" : ""}
      />
      <span>${escapeHTML(student.name)}</span>
    </label>
  `).join("");

  bulkStudentList.querySelectorAll("input[data-student-id]").forEach(checkbox => {
    checkbox.addEventListener("change", () => {
      const studentId = String(checkbox.dataset.studentId || "");
      if (checkbox.checked) bulkSelectedStudentIds.add(studentId);
      else bulkSelectedStudentIds.delete(studentId);
      updateBulkSelectedCount();
    });
  });
}

function setGuideBulkMode(enabled) {
  guideBulkMode = Boolean(enabled);
  bulkSelectedStudentIds.clear();

  if (bulkStudentSearch) bulkStudentSearch.value = "";
  if (addStudent) {
    addStudent.classList.toggle("hidden", guideBulkMode);
    addStudent.required = !guideBulkMode;
  }
  if (bulkStudentPicker) bulkStudentPicker.classList.toggle("hidden", !guideBulkMode);
  if (addViolationSubmitBtn) addViolationSubmitBtn.classList.toggle("hidden", guideBulkMode);

  if (guideBulkMode) {
    renderBulkStudentPicker();
  } else {
    updateAddViolationSubmitButton();
  }
}

function setAddViolationDateMode(mode = "exact") {
  const monthOnly = mode === "month";

  if (addDate) {
    addDate.classList.toggle("hidden", monthOnly);
    addDate.required = !monthOnly;
    if (!addDate.value) addDate.value = getTodayISO();
  }

  if (addMonth) {
    addMonth.classList.toggle("hidden", !monthOnly);
    addMonth.required = monthOnly;
    if (!addMonth.value) addMonth.value = getCurrentMonthISO();
  }

  if (exactViolationDateBtn) exactViolationDateBtn.classList.toggle("active", !monthOnly);
  if (monthOnlyViolationDateBtn) monthOnlyViolationDateBtn.classList.toggle("active", monthOnly);
}

function getAddViolationDateValue() {
  const monthOnly = addMonth && !addMonth.classList.contains("hidden");
  return monthOnly ? addMonth.value : (addDate ? addDate.value : "");
}

function populateAddForm() {
  if (!addStudent || !addViolationType) return;

  addStudent.innerHTML = `<option value="">Select Student</option>`;

  [...students]
    .sort((a, b) =>
      a.lastName.localeCompare(b.lastName) ||
      a.firstName.localeCompare(b.firstName)
    )
    .forEach(student => {
      addStudent.innerHTML += `
        <option value="${student.id}">
          ${student.name}
        </option>
      `;
    });

  addViolationType.innerHTML = `<option value="">Select Violation</option>`;

  violationFees.forEach(v => {
    addViolationType.innerHTML += `
      <option value="${v.name}">
        ${v.name}
      </option>
    `;
  });

  if (addDate) addDate.value = getTodayISO();
  if (addMonth) addMonth.value = getCurrentMonthISO();
  setAddViolationDateMode("exact");
}

function applyKindnessSuggestionFromSelectedViolation() {
  syncKindnessTaskForForm(addSettlementType, addViolationType, addKindnessTask);
}

async function saveViolationRecords(payload, studentIds) {
  const adapter = window.SFK_KINDTRACK_FIREBASE_ADAPTER;

  if (adapter && typeof adapter.saveViolations === "function") {
    return adapter.saveViolations(payload, studentIds);
  }

  if (studentIds.length > 1) {
    const response = await fetch(API_URL, {
      method: "POST",
      body: JSON.stringify({
        ...payload,
        action: "bulkAddViolations",
        studentIds
      })
    });
    return response.json();
  }

  const response = await fetch(API_URL, {
    method: "POST",
    body: JSON.stringify({
      ...payload,
      action: "addViolation",
      studentId: studentIds[0]
    })
  });
  return response.json();
}

async function saveViolation(event) {
  event.preventDefault();

  applyPaidWithKindnessStatus(addStatus, addSettlementType, addViolationType, addKindnessTask, addKindnessStatus, addKindnessCompletedDate, addAdvancedFields);
  syncKindnessCompletedDateForStatus(addKindnessStatus, addKindnessCompletedDate);
  syncKindnessTaskForForm(addSettlementType, addViolationType, addKindnessTask);

  const violationInfo = violationFees.find(v => v.name === addViolationType.value);
  const studentIds = guideBulkMode
    ? Array.from(bulkSelectedStudentIds)
    : [addStudent ? addStudent.value : ""].filter(Boolean);

  if (!studentIds.length) {
    if (addMessage) {
      addMessage.classList.remove("hidden");
      addMessage.textContent = "Select at least one student.";
    }
    showToast("Select at least one student.");
    return;
  }

  if (!addViolationType || !addViolationType.value) {
    if (addMessage) {
      addMessage.classList.remove("hidden");
      addMessage.textContent = "Select a violation type.";
    }
    showToast("Select a violation type.");
    if (addViolationType) addViolationType.focus();
    return;
  }

  const selectedViolationDate = getAddViolationDateValue();
  if (!selectedViolationDate) {
    const monthOnly = addMonth && !addMonth.classList.contains("hidden");
    const message = monthOnly
      ? "Select the violation month and year."
      : "Select the violation date.";
    if (addMessage) {
      addMessage.classList.remove("hidden");
      addMessage.textContent = message;
    }
    showToast(message);
    const fieldToFocus = monthOnly ? addMonth : addDate;
    if (fieldToFocus) fieldToFocus.focus();
    return;
  }

  const payload = {
    violationType: addViolationType.value,
    fee: violationInfo ? violationInfo.fee : 0,
    status: addStatus.value,
    actionTaken: addActionTaken ? addActionTaken.value : "",
    reflection: addReflection ? addReflection.value : "",
    followUpDate: addFollowUpDate ? addFollowUpDate.value : "",
    followUpStatus: addFollowUpStatus ? addFollowUpStatus.value : "Pending",
    parentContacted: addParentContacted ? addParentContacted.value : "No",
    settlementType: addSettlementType ? addSettlementType.value : "Cash",
    kindnessTask: addKindnessTask ? addKindnessTask.value : "",
    kindnessStatus: addKindnessStatus ? addKindnessStatus.value : "Pending",
    kindnessCompletedDate: addKindnessCompletedDate ? addKindnessCompletedDate.value : "",
    date: selectedViolationDate,
    datePrecision: selectedViolationDate.length === 7 ? "month" : "exact",
    notes: addNotes.value,
    encodedBy: "Sir JR"
  };

  try {
    updateAddViolationSubmitButton(true);
    addMessage.classList.remove("hidden");
    addMessage.textContent = studentIds.length > 1
      ? `Saving for ${studentIds.length} students...`
      : "Saving violation...";

    const result = await saveViolationRecords(payload, studentIds);

    if (result.success) {
      const recordIds = Array.isArray(result.recordIds) ? result.recordIds : [result.recordId || ""];
      studentIds.forEach((studentId, index) => {
        const student = students.find(item => String(item.id) === String(studentId));
        if (!student) return;

        student.violations.push({
          recordId: recordIds[index] || `TEMP-${Date.now()}-${index}`,
          date: payload.date,
          type: payload.violationType,
          fee: payload.fee,
          status: payload.status,
          actionTaken: payload.actionTaken,
          reflection: payload.reflection,
          followUpDate: payload.followUpDate,
          followUpStatus: payload.followUpStatus,
          parentContacted: payload.parentContacted,
          settlementType: payload.settlementType,
          kindnessTask: payload.kindnessTask,
          kindnessStatus: payload.kindnessStatus,
          kindnessCompletedDate: payload.kindnessCompletedDate,
          notes: payload.notes
        });
      });

      selectedStudent = students.find(item => String(item.id) === String(studentIds[0])) || selectedStudent;

      const savedMessage = studentIds.length > 1
        ? `Violation saved for ${studentIds.length} students.`
        : "Violation saved successfully.";
      addMessage.textContent = savedMessage;
      showToast(savedMessage);

      addForm.reset();
      setGuideBulkMode(false);
      populateAddForm();
      closeAddViolationModal();
      renderAll();

      loadDataFromSheets().catch(error => {
        console.error("Violation refresh error:", error);
      });

    } else {
      const errorMessage = result.message || "Unable to save violation.";
      addMessage.textContent = errorMessage;
      showToast(errorMessage);
    }
  } catch (error) {
    console.error(error);
    addMessage.classList.remove("hidden");
    const errorMessage = error && error.message ? error.message : "Connection error.";
    addMessage.textContent = errorMessage;
    showToast(errorMessage);
  } finally {
    updateAddViolationSubmitButton(false);
  }
}

function editViolation(recordId) {
  const violation = selectedStudent.violations.find(v => v.recordId === recordId);

  if (!violation) return;

  editViolationType.innerHTML = "";

  violationFees.forEach(v => {
    editViolationType.innerHTML += `
      <option value="${v.name}">
        ${v.name}
      </option>
    `;
  });

  editRecordId.value = violation.recordId;
  editViolationType.value = violation.type;
  editStatus.value = violation.status;
  if (editSettlementType) {
    editSettlementType.value = violation.settlementType || "Cash";
  }
  if (editKindnessTask) {
    editKindnessTask.value = violation.kindnessTask || "";
  }
  if (editKindnessStatus) {
    editKindnessStatus.value = violation.kindnessStatus || "Pending";
  }
  if (editKindnessCompletedDate) {
    editKindnessCompletedDate.value = violation.kindnessCompletedDate || "";
  }
  if (editActionTaken) {
    editActionTaken.value = violation.actionTaken || "Verbal Reminder";
  }
  if (editReflection) {
    editReflection.value = violation.reflection || "";
  }
  if (editFollowUpDate) {
    editFollowUpDate.value = violation.followUpDate || "";
  }
  if (editFollowUpStatus) {
    editFollowUpStatus.value = violation.followUpStatus || "Pending";
  }
  if (editParentContacted) {
    editParentContacted.value = violation.parentContacted || "No";
  }
  const violationDateValue = String(violation.date || "");
  if (editDate) {
    editDate.type = /^\d{4}-\d{2}$/.test(violationDateValue) ? "month" : "date";
    editDate.value = violationDateValue;
  }
  editNotes.value = violation.notes || "";
  if (isPaidWithKindnessStatus(editStatus ? editStatus.value : violation.status)) {
    applyPaidWithKindnessStatus(editStatus, editSettlementType, editViolationType, editKindnessTask, editKindnessStatus, editKindnessCompletedDate, null);
  } else if (!editKindnessTask || !editKindnessTask.value.trim()) {
    if (editKindnessTask) editKindnessTask.dataset.autoSuggested = "true";
    applyPaidWithKindnessStatus(editStatus, editSettlementType, editViolationType, editKindnessTask, editKindnessStatus, editKindnessCompletedDate, null);
    syncKindnessTaskForForm(editSettlementType, editViolationType, editKindnessTask);
  }

  syncKindnessCompletedDateForStatus(editKindnessStatus, editKindnessCompletedDate);

  openModal(editModal);
}

async function saveEditedViolation(event) {
  event.preventDefault();
  applyPaidWithKindnessStatus(editStatus, editSettlementType, editViolationType, editKindnessTask, editKindnessStatus, editKindnessCompletedDate, null);
  syncKindnessCompletedDateForStatus(editKindnessStatus, editKindnessCompletedDate);
  syncKindnessTaskForForm(editSettlementType, editViolationType, editKindnessTask);

  const violationInfo = violationFees.find(v => v.name === editViolationType.value);

  const payload = {
    action: "editViolation",
    recordId: editRecordId.value,
    date: editDate.value,
    violationType: editViolationType.value,
    fee: violationInfo ? violationInfo.fee : 0,
    status: editStatus.value,
    actionTaken: editActionTaken ? editActionTaken.value : "",
    reflection: editReflection ? editReflection.value : "",
    followUpDate: editFollowUpDate ? editFollowUpDate.value : "",
    followUpStatus: editFollowUpStatus ? editFollowUpStatus.value : "Pending",
    parentContacted: editParentContacted ? editParentContacted.value : "No",
    settlementType: editSettlementType ? editSettlementType.value : "Cash",
    kindnessTask: editKindnessTask ? editKindnessTask.value : "",
    kindnessStatus: editKindnessStatus ? editKindnessStatus.value : "Pending",
    kindnessCompletedDate: editKindnessCompletedDate ? editKindnessCompletedDate.value : "",
    notes: editNotes.value
  };

  try {
    showToast("Saving changes...");

    const response = await fetch(API_URL, {
      method: "POST",
      body: JSON.stringify(payload)
    });

    const result = await response.json();

    if (result.success) {
      const record = selectedStudent.violations.find(
        v => v.recordId === payload.recordId
      );

      if (record) {
        record.date = payload.date;
        record.type = payload.violationType;
        record.fee = payload.fee;
        record.status = payload.status;
        record.actionTaken = payload.actionTaken;
        record.reflection = payload.reflection;
        record.followUpDate = payload.followUpDate;
        record.followUpStatus = payload.followUpStatus;
        record.parentContacted = payload.parentContacted;
        record.settlementType = payload.settlementType;
        record.kindnessTask = payload.kindnessTask;
        record.kindnessStatus = payload.kindnessStatus;
        record.kindnessCompletedDate = payload.kindnessCompletedDate;
        record.notes = payload.notes;
      }

      await loadDataFromSheets();
      editModal.classList.add("hidden");
      showToast("✅ Violation updated successfully.");

    } else {
      showToast("❌ Unable to update violation.");
    }
  } catch (error) {
    console.error(error);
    showToast("❌ Connection error.");
  }
}

function deleteViolation(recordId) {
  if (!deleteModal || !deleteRecordId) return;

  deleteRecordId.value = recordId;
  openModal(deleteModal);
}

async function confirmDeleteViolation() {
  const recordId = deleteRecordId.value;

  const payload = {
    action: "deleteViolation",
    recordId
  };

  try {
    showToast("Deleting violation...");

    const response = await fetch(API_URL, {
      method: "POST",
      body: JSON.stringify(payload)
    });

    const result = await response.json();

    if (result.success) {
      if (selectedStudent) {
        selectedStudent.violations = selectedStudent.violations.filter(
          v => v.recordId !== recordId
        );

        const index = students.findIndex(s => s.id === selectedStudent.id);

        if (index !== -1) {
          students[index] = selectedStudent;
        }
      }

      deleteModal.classList.add("hidden");
      renderAll();
      showToast("🗑️ Violation deleted.");

    } else {
      showToast("❌ Unable to delete violation.");
    }
  } catch (error) {
    console.error(error);
    showToast("❌ Unable to delete violation.");
  }
}

