function formatViolationRegisterDate(value) {
  const normalized = formatDate(value || "");
  if (!normalized) return "";

  if (/^\d{4}-\d{2}$/.test(normalized)) {
    return formatDisplayDate(normalized);
  }

  const parts = normalized.split("-");
  if (parts.length === 3) {
    return `${parts[1]}/${parts[2]}/${parts[0]}`;
  }

  return normalized;
}

function getViolationRegisterSettlementDetails(violation) {
  const kindnessRecord = isKindnessRecord(violation);
  const kindnessSettled = kindnessRecord && (
    isKindnessCompleted(violation) ||
    isPaidStatus(violation.status) ||
    isPaidWithKindnessStatus(violation.status)
  );
  const cashSettled = !kindnessRecord && isPaidStatus(violation.status);
  const waived = isWaivedStatus(violation.status);

  let settlementValue = "";
  let dateDetails = "";
  let status = "";

  if (cashSettled) {
    settlementValue = `₱${Number(violation.fee) || 0}`;
    const paymentDate = violation.paymentDate || violation.datePaid || violation.paidDate || violation.settlementDate || "";
    dateDetails = paymentDate
      ? `Paid: ${formatViolationRegisterDate(paymentDate)}`
      : "Paid: __________";
    status = "Paid";
  } else if (kindnessSettled) {
    settlementValue = getEffectiveKindnessTask(violation) || "________________";
    const kindnessStartDate = violation.kindnessStartDate || violation.startDate || "";
    const kindnessCompletedDate = getEffectiveKindnessCompletedDate(violation);
    const dateParts = [
      kindnessStartDate
        ? `Start: ${formatViolationRegisterDate(kindnessStartDate)}`
        : "Start: __________",
      kindnessCompletedDate
        ? `Completed: ${formatViolationRegisterDate(kindnessCompletedDate)}`
        : "Completed: __________"
    ];

    dateDetails = dateParts.join("<br>");
    status = "Completed";
  } else if (waived) {
    status = "Waived";
  }

  return {
    cashChecked: cashSettled,
    kindnessChecked: kindnessSettled,
    settlementValue,
    dateDetails,
    status,
    encodedChecked: cashSettled || kindnessSettled ||
      violation.encodedInKindnessApp === true ||
      ["yes", "true", "encoded"].includes(String(violation.encodedInKindnessApp || "").trim().toLowerCase())
  };
}

function getViolationDateInterval(value) {
  const normalized = formatDate(value || "");

  if (/^\d{4}-\d{2}$/.test(normalized)) {
    const [yearText, monthText] = normalized.split("-");
    const year = Number(yearText);
    const month = Number(monthText);

    if (!year || month < 1 || month > 12) return null;

    const lastDay = new Date(year, month, 0).getDate();
    return {
      start: `${yearText}-${monthText}-01`,
      end: `${yearText}-${monthText}-${String(lastDay).padStart(2, "0")}`
    };
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(normalized)) {
    return { start: normalized, end: normalized };
  }

  return null;
}

function getViolationPrintDateFilter() {
  const start = String(violationPrintFromDate?.value || "").trim();
  const end = String(violationPrintToDate?.value || "").trim();

  if (start && end && start > end) {
    showToast("The From date must be earlier than or the same as the To date.");
    return { valid: false, start, end, label: "" };
  }

  let label = "All violation dates";
  if (start && end) {
    label = `${formatDisplayDate(start)} to ${formatDisplayDate(end)}`;
  } else if (start) {
    label = `From ${formatDisplayDate(start)}`;
  } else if (end) {
    label = `Up to ${formatDisplayDate(end)}`;
  }

  return { valid: true, start, end, label };
}

function violationMatchesPrintDateRange(value, start, end) {
  if (!start && !end) return true;

  const interval = getViolationDateInterval(value);
  if (!interval) return false;

  if (start && interval.end < start) return false;
  if (end && interval.start > end) return false;
  return true;
}

function getViolationRegisterRows(dateFilter = null) {
  const sortedStudents = [...students].sort((a, b) =>
    String(a.lastName || "").localeCompare(String(b.lastName || ""), undefined, { sensitivity: "base" }) ||
    String(a.firstName || "").localeCompare(String(b.firstName || ""), undefined, { sensitivity: "base" })
  );

  const rows = [];

  sortedStudents.forEach(student => {
    const violations = [...getVisibleViolations(student)].sort((a, b) =>
      String(a.date || "").localeCompare(String(b.date || "")) ||
      String(a.type || "").localeCompare(String(b.type || ""), undefined, { sensitivity: "base" })
    );

    violations.forEach(violation => {
      if (
        dateFilter &&
        !violationMatchesPrintDateRange(violation.date || "", dateFilter.start, dateFilter.end)
      ) {
        return;
      }

      rows.push({
        studentId: String(student.id || student.name || ""),
        studentName: student.name || `${student.lastName || ""}, ${student.firstName || ""}`.trim(),
        violation
      });
    });
  });

  return rows;
}

